    $types = $pdo->query('SELECT jenis_surat_id,nama_jenis FROM jenis_surat ORDER BY nama_jenis')->fetchAll();
    $classes = $pdo->query('SELECT klasifikasi_id,nama_klasifikasi FROM klasifikasi_arsip ORDER BY nama_klasifikasi')->fetchAll();
    $sql = 'SELECT a.arsip_id,a.no_registrasi,a.no_surat,a.perihal,a.tanggal_surat,a.status_arsip,u.nama_unit,j.nama_jenis,COALESCE(k.nama_klasifikasi, \'-\') nama_klasifikasi FROM arsip a JOIN unit_kerja u ON u.unit_id=a.unit_id JOIN jenis_surat j ON j.jenis_surat_id=a.jenis_surat_id LEFT JOIN klasifikasi_arsip k ON k.klasifikasi_id=a.klasifikasi_id WHERE (a.no_registrasi LIKE :q1 OR a.no_surat LIKE :q2 OR a.perihal LIKE :q3)';
    $params = ['q1' => "%$q%", 'q2' => "%$q%", 'q3' => "%$q%"];
    foreach (['unit_id' => $unitId, 'jenis_surat_id' => $typeId, 'klasifikasi_id' => $classId] as $column => $value) { if ($value > 0) { $sql .= " AND a.$column = :$column"; $params[$column] = $value; } }
    if (in_array($status, ['Aktif', 'Permanen', 'Musnah'], true)) { $sql .= ' AND a.status_arsip = :status'; $params['status'] = $status; }
    if ($from !== '') { $sql .= ' AND a.tanggal_surat >= :from'; $params['from'] = $from; }
    if ($to !== '') { $sql .= ' AND a.tanggal_surat <= :to'; $params['to'] = $to; }
    $s = $pdo->prepare($sql . ' ORDER BY a.created_at DESC LIMIT 100'); $s->execute($params); $items = $s->fetchAll();
